return {["fb07_01"]={["BgmDown"]=1,["dsc"]=[[树林里光线暗淡，只能听见头顶上传来一些鸟儿的啼鸣。偶而从茂密的叶间透过的一线光伴着落叶在飞舞。朽木腐烂的气味和身後传来野兽的啸声使人不觉犹豫了前进的脚步。]],["enterable"]=1,["fightBackground"]=[[树林内]],["id"]=[[fb07_01]],["name"]=[[树林]],["permission"]=2,["right"]=[[fb07_02]],["role1"]=[[fb07r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb07_03]],["visible"]=1},["fb07_02"]={["BgmDown"]=1,["dsc"]=[[树林里光线暗淡，只能听见头顶上传来一些鸟儿的啼鸣。偶而从茂密的叶间透过的一线光伴着落叶在飞舞。朽木腐烂的气味和身後传来野兽的啸声使人不觉犹豫了前进的脚步。林中立着一块牌子。]],["enterable"]=1,["fightBackground"]=[[树林内]],["id"]=[[fb07_02]],["item1"]=[[bfitem3]],["left"]=[[fb07_01]],["name"]=[[树林]],["permission"]=2,["role1"]=[[fb07r02_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb07_04]],["visible"]=1},["fb07_03"]={["BgmDown"]=1,["down"]=[[fb07_01]],["dsc"]=[[树林里光线暗淡，只能听见头顶上传来一些鸟儿的啼鸣。偶而从茂密的叶间透过的一线光伴着落叶在飞舞。朽木腐烂的气味和身後传来野兽的啸声使人不觉犹豫了前进的脚步。]],["enterable"]=1,["fightBackground"]=[[树林内]],["id"]=[[fb07_03]],["leftUp"]=[[fb07_06]],["name"]=[[树林]],["permission"]=2,["right"]=[[fb07_04]],["role1"]=[[fb07r03_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb07_04"]={["down"]=[[fb07_02]],["dsc"]=[[树林里光线暗淡，只能听见头顶上传来一些鸟儿的啼鸣。偶而从茂密的叶间透过的一线光伴着落叶在飞舞。朽木腐烂的气味和身後传来野兽的啸声使人不觉犹豫了前进的脚步。]],["enterable"]=1,["fightBackground"]=[[树林内]],["id"]=[[fb07_04]],["left"]=[[fb07_03]],["name"]=[[树林]],["permission"]=2,["role1"]=[[fb07r04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb07_08]],["visible"]=1},["fb07_05"]={["dsc"]=[[树林里光线暗淡，只能听见头顶上传来一些鸟儿的啼鸣。偶而从茂密的叶间透过的一线光伴着落叶在飞舞。朽木腐烂的气味和身後传来野兽的啸声使人不觉犹豫了前进的脚步。]],["enterable"]=1,["fightBackground"]=[[树林内]],["id"]=[[fb07_05]],["item1"]=[[fb07item20]],["name"]=[[树林]],["permission"]=2,["right"]=[[fb07_06]],["role1"]=[[fb07r05_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb07_06"]={["BgmDown"]=1,["dsc"]=[[树林里光线暗淡，只能听见头顶上传来一些鸟儿的啼鸣。偶而从茂密的叶间透过的一线光伴着落叶在飞舞。朽木腐烂的气味和身後传来野兽的啸声使人不觉犹豫了前进的脚步。]],["enterable"]=1,["fightBackground"]=[[树林内]],["id"]=[[fb07_06]],["left"]=[[fb07_05]],["name"]=[[树林]],["permission"]=2,["rightDown"]=[[fb07_03]],["rightUp"]=[[fb07_07]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]